<?php declare(strict_types=1);
$pageUrl = static function (int $page) use ($baseUrl, $roleFilter, $statusFilter, $searchQuery): string {
    return $baseUrl . '/admin/accounts?' . http_build_query(array_filter([
        'page' => $page, 'role' => $roleFilter, 'status' => $statusFilter, 'q' => $searchQuery,
    ], static fn (mixed $value): bool => $value !== ''));
};
?>
<header class="resource-header"><div><span class="booking-eyebrow">Quản trị truy cập</span><h1>Quản lý tài khoản</h1><p>Khóa hoặc mở tài khoản; vai trò và quan hệ tổ chức không bị sửa tại màn hình này.</p></div><span class="queue-count"><strong><?= (int) $pageData['total'] ?></strong> tài khoản</span></header>
<section class="resource-surface admin-workspace">
<form class="resource-toolbar admin-filter-bar" method="get" action="<?= $baseUrl ?>/admin/accounts"><label class="toolbar-search"><svg class="app-icon"><use href="#icon-search"/></svg><span class="visually-hidden">Tìm tài khoản</span><input type="search" name="q" value="<?= $searchQuery ?>" placeholder="Mã, họ tên hoặc email"></label><label class="toolbar-select"><span class="visually-hidden">Vai trò</span><select name="role"><option value="">Mọi vai trò</option><?php foreach (['CUSTOMER'=>'Customer','PARTNER'=>'Partner','ADMIN'=>'Admin'] as $code=>$label): ?><option value="<?= $code ?>"<?= $roleFilter===$code?' selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label class="toolbar-select"><span class="visually-hidden">Trạng thái</span><select name="status"><option value="">Mọi trạng thái</option><option value="HOAT_DONG"<?= $statusFilter==='HOAT_DONG'?' selected':'' ?>>Hoạt động</option><option value="KHOA"<?= $statusFilter==='KHOA'?' selected':'' ?>>Đã khóa</option></select></label><button class="button button--secondary button--small" type="submit">Lọc</button></form>
<div class="resource-table-wrap"><table class="resource-table"><thead><tr><th>Tài khoản</th><th>Liên hệ</th><th>Vai trò / tổ chức</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($pageData['items'] as $account): ?><tr><td><strong><?= $account['fullName'] ?></strong><small><?= $account['code'] ?></small></td><td><?= $account['email'] ?><small><?= $account['phone'] ?? '—' ?></small></td><td><strong><?= $account['role'] ?></strong><small><?= $account['organizationName'] ?? 'Không thuộc tổ chức' ?></small></td><td><span class="booking-status booking-status--<?= strtolower((string) $account['status']) ?>"><i></i><?= $account['status']==='HOAT_DONG'?'Hoạt động':'Đã khóa' ?></span></td><td><form method="post" action="<?= $baseUrl ?>/admin/accounts/<?= (int) $account['id'] ?>/status"><input type="hidden" name="_token" value="<?= $csrfToken ?>"><input type="hidden" name="status" value="<?= $account['status']==='HOAT_DONG'?'KHOA':'HOAT_DONG' ?>"><button class="button button--<?= $account['status']==='HOAT_DONG'?'danger':'secondary' ?> button--small" type="submit"><?= $account['status']==='HOAT_DONG'?'Khóa':'Mở khóa' ?></button></form></td></tr><?php endforeach; ?><?php if ($pageData['items']===[]): ?><tr><td colspan="5"><div class="empty-state">Không có tài khoản phù hợp.</div></td></tr><?php endif; ?></tbody></table></div>
<footer class="resource-footer booking-pagination"><span>Trang <strong><?= (int) $pageData['page'] ?></strong> / <?= (int) $pageData['pageCount'] ?></span><span class="booking-pagination__links"><?php if ($pageData['page']>1): ?><a class="button button--secondary button--small" href="<?= $pageUrl((int)$pageData['page']-1) ?>">Trang trước</a><?php endif; ?><?php if ($pageData['page']<$pageData['pageCount']): ?><a class="button button--secondary button--small" href="<?= $pageUrl((int)$pageData['page']+1) ?>">Trang sau</a><?php endif; ?></span></footer>
</section>
